    private fun parse(s: String) = s.split("|").map { val i = it.indexOf(' '); if (i < 0) it to "" else it.substring(0, i) to it.substring(i + 1) }

    /** emoji to search keywords, one list per category in [categoryNames] order */
    val byCategory: List<List<Pair<String, String>>> = RAW.map { parse(it) }

    val all: List<Pair<String, String>> = byCategory.flatten()
}
